import { Group, Mesh, PlaneGeometry, BoxGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { vec3, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const root = new Group();
  root.name = config.id ?? 'features-card-1';

  const resources = [];
  const primitiveResults = [];
  let disposed = false;

  const stageMaterial = new MeshBasicNodeMaterial({
    color: colors.surface
  });
  stageMaterial.colorNode = mix(
    vec3(colors.surface),
    vec3(colors.ink),
    uv().y
  );

  const stage = new Mesh(
    new PlaneGeometry(7, 6),
    stageMaterial
  );
  stage.name = 'engineered-gradient-stage';
  stage.position.set(0, 0, -2.5);
  root.add(stage);
  resources.push(stage.geometry, stage.material);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.52,
    depthWrite: false
  });

  const shadow = new Mesh(
    new PlaneGeometry(3.45, 2.25),
    shadowMaterial
  );
  shadow.name = 'card-contact-shadow';
  shadow.position.set(0.08, -0.08, -0.24);
  root.add(shadow);
  resources.push(shadow.geometry, shadow.material);

  const backingMaterial = new MeshBasicNodeMaterial({
    color: colors.ink
  });

  const backing = new Mesh(
    new BoxGeometry(3.16, 2.01, 0.12),
    backingMaterial
  );
  backing.name = 'machined-card-body';
  backing.position.set(0, 0, -0.1);
  root.add(backing);
  resources.push(backing.geometry, backing.material);

  const imageMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0
  });

  const imagePlane = new Mesh(
    new PlaneGeometry(3.04, 1.9),
    imageMaterial
  );
  imagePlane.name = 'feature-card-image';
  imagePlane.position.set(0, 0, 0.01);
  root.add(imagePlane);
  resources.push(imagePlane.geometry, imagePlane.material);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });

  const accentRule = new Mesh(
    new BoxGeometry(0.035, 1.46, 0.025),
    accentMaterial
  );
  accentRule.name = 'signal-red-machined-rule';
  accentRule.position.set(1.43, 0, 0.055);
  root.add(accentRule);
  resources.push(accentRule.geometry, accentRule.material);

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.42
  });

  const edge = new Mesh(
    new BoxGeometry(2.35, 0.018, 0.018),
    edgeMaterial
  );
  edge.name = 'paper-edge-detail';
  edge.position.set(-0.2, -0.78, 0.06);
  root.add(edge);
  resources.push(edge.geometry, edge.material);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string' || !item.text) continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 32,
      color: item.role === 'accent' ? colors.accent : colors.paper,
      align: item.typography?.align ?? 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.position.set(
      item.position?.x ?? -1.05,
      item.position?.y ?? 0.78,
      item.position?.z ?? 0.08
    );
    root.add(textObject);
  }

  const timeline = gsap.timeline({
    defaults: {
      overwrite: 'auto'
    }
  });

  timeline
    .fromTo(
      backing.scale,
      { x: 0.96, y: 0.96, z: 0.96 },
      { x: 1.04, y: 1.04, z: 1.04, duration: 0.42, ease: 'power3.out' }
    )
    .to(
      backing.scale,
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
    )
    .fromTo(
      imageMaterial,
      { opacity: 0 },
      { opacity: 1, duration: 0.55, ease: 'power2.out' },
      '-=0.64'
    )
    .fromTo(
      [accentRule.scale, edge.scale],
      { x: 0.7, y: 0.7, z: 0.7 },
      { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power3.out' },
      '-=0.32'
    );

  if (config.cinematicPrimitives?.length) {
    for (const primitive of config.cinematicPrimitives) {
      const handler = ctx.primitives?.[primitive.name];
      if (typeof handler === 'function') {
        primitiveResults.push(
          handler(root, primitive.params ?? {})
        );
      }
    }
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      resources.push(texture);
    });
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    timeline.kill();

    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.clear();
  };

  return root;
}
